-- CREATE: creates a new table
CREATE TABLE employees (id INT PRIMARY KEY, name VARCHAR(100));

-- ALTER: modify existing table structure
ALTER TABLE employees ADD COLUMN salary DECIMAL(10,2);

-- TRUNCATE: remove all rows, keep structure
TRUNCATE TABLE employees;

-- DROP: permanently delete the table
DROP TABLE employees;

-- INSERT: add a new row
INSERT INTO employees (name, salary) VALUES ('Alice', 75000);

-- UPDATE: modify existing rows
UPDATE employees SET salary = 80000 WHERE id = 1;

-- DELETE: remove specific rows
DELETE FROM employees WHERE id = 1;

-- Without WHERE — affects ALL rows!
UPDATE employees SET salary = 0; -- DANGEROUS

BEGIN;
INSERT INTO accounts (id, balance) VALUES (1, 1000);
SAVEPOINT after_insert;

UPDATE accounts SET balance = -500 WHERE id = 1;
-- Something went wrong!
ROLLBACK TO SAVEPOINT after_insert;

-- First insert is preserved
COMMIT;
